#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

/*
 * Reconstructed program behavior:
 *   - If no command‑line argument is supplied, prints "NO_INPUT".
 *   - Parses the first argument as a base‑10 integer.
 *   - If parsing fails or extra characters remain, prints "BAD_INPUT".
 *   - If the number is negative, prints "NEGATIVE".
 *   - If the number is greater than 90, prints "OUT_OF_RANGE".
 *   - Otherwise computes the n‑th Fibonacci number (0‑based) using
 *     memoised recursion and prints it as a signed 64‑bit integer.
 */

static long long memo[91];
static char computed[91];

static long long fib(int n)
{
    if (n < 0) {
        return 0; // should never happen for valid inputs
    }
    if (computed[n]) {
        return memo[n];
    }
    if (n == 0) {
        memo[0] = 0;
        computed[0] = 1;
        return 0;
    }
    if (n == 1) {
        memo[1] = 1;
        computed[1] = 1;
        return 1;
    }
    long long a = fib(n - 1);
    long long b = fib(n - 2);
    memo[n] = a + b;
    computed[n] = 1;
    return memo[n];
}

int main(int argc, char **argv)
{
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr;
    long value = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    if (value < 0) {
        puts("NEGATIVE");
        return 0;
    }
    if (value > 90) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    long long result = fib((int)value);
    printf("%lld\n", result);
    return 0;
}
